function calculateScore(s) {
  const stacks = Array.from({ length: 26 }, () => []);
  let score = 0;
  for (let i = 0; i < s.length; i++) {
    const letter = s.charCodeAt(i) - 97;
    const mirror = 25 - letter;
    const waiting = stacks[mirror];
    if (waiting.length > 0) {
      const j = waiting.pop();
      score += i - j;
    } else {
      stacks[letter].push(i);
    }
  }
  return score;
}

