function calculateScore(s) {
  // Follow the process literally: scan left from every index for the nearest unmarked mirror letter.
  const marked = new Array(s.length).fill(false);
  let total = 0;
  for (let i = 0; i < s.length; i++) {
    const want = String.fromCharCode('a'.charCodeAt(0) + 'z'.charCodeAt(0) - s.charCodeAt(i));
    for (let j = i - 1; j >= 0; j--) {
      if (!marked[j] && s[j] === want) {
        marked[i] = true;
        marked[j] = true;
        total += i - j;
        break;
      }
    }
  }
  return total;
}

