function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  // Small alphabets full of mirror pairs make many matches; 'abc' has no mirror pairs at all.
  const alphabets = ['az', 'abyz', 'mn', 'mnop', 'abc', 'abcxyz', 'abcdefghijklmnopqrstuvwxyz'];
  const letters = alphabets[pick(alphabets.length)];
  const length = size === 'large' ? 10000 : 1 + pick(12);
  let s = '';
  for (let i = 0; i < length; i++) s += letters[pick(letters.length)];
  return [s];
}
